with deduped as (select id, page, event_time, duration_sec from (select *, row_number() over (partition by page, session_id order by event_time desc nulls last, id) as latest_rank from web_events) t where latest_rank = 1) select date_trunc('quarter', event_time) as quarter_start, page, case when duration_sec >= 464 then 'PREMIUM' else 'STANDARD' end as duration_sec_tier, round(avg(duration_sec), 2) as avg_duration_sec, count(distinct page) as distinct_pages from deduped group by grouping sets ((date_trunc('quarter', event_time), page, case when duration_sec >= 464 then 'PREMIUM' else 'STANDARD' end), (date_trunc('quarter', event_time), page), (date_trunc('quarter', event_time))) having avg_duration_sec < 1000000
